-- Repair three things a learner hit on a phone.
--
-- All three were live, all three made a question unanswerable or unreadable,
-- and none of them was visible from the database alone.
--
-- 1. A chip with no furigana. 早く is 早い bent into an adverb: the dictionary
--    reading はやい does not align with 早く, and the line's own reading gave
--    just く, so the token ended up with NO reading. A chip without ruby renders
--    as the bare kanji — the word-order question showed 早く with "早 ku" over
--    it — and this is N5, where the kanji is exactly what the reader cannot
--    read. `alignInflected` handles the case; the tokens below are regenerated
--    with it, and 勉強する and 勉強します were in the same state.
--
-- 2. Dictation accepted only kanji. "Listen and type what you hear" answered
--    with 友だちが来る。 asks an N5 learner for an IME and a kanji they have not
--    met, rather than for what they heard. Kana is accepted now — assembled
--    from the TOKENS' ruby, not from `reading_kana`, which is deliberately
--    SPOKEN (は written わ) and would mark わたしわがくせいです correct and teach
--    a misspelling. The tokens spell it as it is written: わたしはがくせいです。
--
-- 3. (Fixed in the frontend, not here.) The lesson never played the clip, so a
--    dictation question asked the reader to transcribe silence.
--
-- Updated in place rather than deleted and re-derived: `lesson_misses` cascades
-- on delete, and those rows are the questions a reader got wrong and is owed
-- again. Re-running changes nothing.

-- 1. The tokens, regenerated.
DELETE FROM sentence_tokens WHERE sentence_id IN ('sent-ex-desu-1', 'sent-ex-desu-2', 'sent-ex-desu-4', 'sent-ex-dict-1', 'sent-ex-dict-2', 'sent-ex-dict-3', 'sent-ex-dict-4', 'sent-ex-vclass-2', 'sent-ex-vclass-3', 'sent-ex-vclass-4', 'sent-ex-masu-1', 'sent-ex-masu-3', 'sent-ex-masu-4', 'sent-ex-te-1', 'sent-ex-te-2', 'sent-ex-te-3', 'sent-ex-te-4', 'sent-ex-ta-1', 'sent-ex-ta-2', 'sent-ex-ta-3', 'sent-ex-ta-4', 'sent-ex-teiru-1', 'sent-ex-teiru-2', 'sent-ex-teiru-3', 'sent-ex-teiru-4', 'sent-ex-nai-1', 'sent-ex-nai-2', 'sent-ex-nai-3', 'sent-ex-nai-4', 'sent-ex-desu-3', 'sent-ex-vclass-1', 'sent-ex-masu-2', 'sent-ex-wa-1', 'sent-ex-wa-2', 'sent-ex-wa-3', 'sent-ex-wa-4', 'sent-ex-ga-1', 'sent-ex-ga-2', 'sent-ex-ga-3', 'sent-ex-ga-4', 'sent-ex-kudasai-1', 'sent-ex-kudasai-2', 'sent-ex-kudasai-3', 'sent-ex-kudasai-4', 'sent-ex-mashou-1', 'sent-ex-mashou-2', 'sent-ex-mashou-3', 'sent-ex-mashou-4', 'sent-ex-tai-1', 'sent-ex-tai-2', 'sent-ex-tai-3', 'sent-ex-tai-4', 'sent-ex-kara-1', 'sent-ex-kara-2', 'sent-ex-kara-3', 'sent-ex-kara-4', 'sent-ex-ni-1', 'sent-ex-ni-2', 'sent-ex-ni-3', 'sent-ex-ni-4', 'sent-ex-wo-1', 'sent-ex-wo-2', 'sent-ex-wo-3', 'sent-ex-wo-4', 'sent-ex-mo-1', 'sent-ex-mo-2', 'sent-ex-mo-3', 'sent-ex-mo-4', 'sent-ex-aru-1', 'sent-ex-aru-2', 'sent-ex-aru-3', 'sent-ex-aru-4', 'sent-ex-no-1', 'sent-ex-no-2', 'sent-ex-no-3', 'sent-ex-no-4', 'sent-ex-ka-1', 'sent-ex-ka-2', 'sent-ex-ka-3', 'sent-ex-ka-4', 'sent-ex-deloc-1', 'sent-ex-deloc-2', 'sent-ex-deloc-3', 'sent-ex-deloc-4', 'sent-ex-demeans-1', 'sent-ex-demeans-2', 'sent-ex-demeans-3', 'sent-ex-demeans-4', 'sent-ex-he-1', 'sent-ex-he-2', 'sent-ex-he-3', 'sent-ex-he-4', 'sent-ex-to-1', 'sent-ex-to-2', 'sent-ex-to-3', 'sent-ex-to-4', 'sent-ex-ya-1', 'sent-ex-ya-2', 'sent-ex-ya-3', 'sent-ex-ya-4', 'sent-ex-gabut-1', 'sent-ex-gabut-2', 'sent-ex-gabut-3', 'sent-ex-gabut-4', 'sent-ex-iadj-1', 'sent-ex-iadj-2', 'sent-ex-iadj-3', 'sent-ex-iadj-4', 'sent-ex-naadj-1', 'sent-ex-naadj-2', 'sent-ex-naadj-3', 'sent-ex-naadj-4', 'sent-ex-karamade-1', 'sent-ex-karamade-2', 'sent-ex-karamade-3', 'sent-ex-karamade-4', 'sent-ex-yori-1', 'sent-ex-yori-2', 'sent-ex-yori-3', 'sent-ex-yori-4', 'sent-ex-masenka-1', 'sent-ex-masenka-2', 'sent-ex-masenka-3', 'sent-ex-masenka-4', 'sent-ex-naide-1', 'sent-ex-naide-2', 'sent-ex-naide-3', 'sent-ex-naide-4', 'sent-ex-takoto-1', 'sent-ex-takoto-2', 'sent-ex-takoto-3', 'sent-ex-takoto-4', 'sent-ex-nagara-1', 'sent-ex-nagara-2', 'sent-ex-nagara-3', 'sent-ex-nagara-4', 'sent-ex-maeni-1', 'sent-ex-maeni-2', 'sent-ex-maeni-3', 'sent-ex-maeni-4', 'sent-ex-atode-1', 'sent-ex-atode-2', 'sent-ex-atode-3', 'sent-ex-atode-4', 'sent-ex-toki-1', 'sent-ex-toki-2', 'sent-ex-toki-3', 'sent-ex-toki-4', 'sent-ex-tara-1', 'sent-ex-tara-2', 'sent-ex-tara-3', 'sent-ex-tara-4');


-- 2. The word-order chips and their ruby, rebuilt from those tokens.
WITH grouped AS (
  SELECT
    st.sentence_id, st.index, st.surface, st.furigana,
    -- A chip starts at every token the dictionary knows, and at every token
    -- longer than one character. An unlinked SINGLE kana is a fragment —
    -- `glossLine` shreds anything outside the published vocabulary, so です
    -- arrives as the real particle で plus an orphan す — and it belongs to the
    -- chip before it. Dragging で and す separately is a puzzle about the
    -- tokeniser, not about Japanese.
    sum(CASE WHEN st.word_id IS NOT NULL OR length(st.surface) > 1 THEN 1 ELSE 0 END)
      OVER (PARTITION BY st.sentence_id ORDER BY st.index
            ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS grp
  FROM sentence_tokens st
  JOIN sentences ss ON ss.id = st.sentence_id AND ss.source = 'authored'
  WHERE st.surface !~ '^[。、！？「」]+$'
),
-- Text and ruby are aggregated SEPARATELY and joined back.
--
-- Doing both in one pass meant lateral-joining the furigana array, which
-- multiplies the row per segment — so a two-segment token had its surface
-- concatenated twice and 朝ご飯を食べる came out as
-- ["朝ご飯","朝ご飯","朝ご飯を","食べる","食べる"].
chip_text AS (
  SELECT sentence_id, grp, min(index) AS pos, string_agg(surface, '' ORDER BY index) AS chip
  FROM grouped GROUP BY sentence_id, grp
),
chip_ruby AS (
  SELECT g.sentence_id, g.grp,
         jsonb_agg(
           CASE WHEN e.seg ? 'r' THEN jsonb_set(e.seg, '{r}', to_jsonb(btrim(e.seg->>'r'))) ELSE e.seg END
           ORDER BY g.index, e.ord
         ) AS ruby
  FROM grouped g
  CROSS JOIN LATERAL jsonb_array_elements(g.furigana) WITH ORDINALITY e(seg, ord)
  GROUP BY g.sentence_id, g.grp
),
chips AS (
  SELECT t.sentence_id, t.pos, t.chip, COALESCE(r.ruby, jsonb_build_array(jsonb_build_object('t', t.chip))) AS ruby
  FROM chip_text t
  LEFT JOIN chip_ruby r ON r.sentence_id = t.sentence_id AND r.grp = t.grp
)
UPDATE exercise_prompts p
SET prompt = p.prompt
      || jsonb_build_object(
           'tokens', (SELECT jsonb_agg(c.chip ORDER BY md5(c.chip || c.sentence_id)) FROM chips c WHERE c.sentence_id = p.assets ->> 'sentenceId'),
           'tokenFurigana', (SELECT jsonb_object_agg(c.chip, c.ruby) FROM chips c WHERE c.sentence_id = p.assets ->> 'sentenceId')
         ),
    updated_at = now()
WHERE p.id LIKE 'ep-wo-%'
  AND EXISTS (SELECT 1 FROM chips c WHERE c.sentence_id = p.assets ->> 'sentenceId');

-- 3. Dictation, which now also accepts the sentence spelled in kana.
UPDATE exercise_prompts p
SET answer = jsonb_build_object(
      'primary', s.text,
      'accepted', jsonb_build_array(
        s.text,
        regexp_replace(s.text, '[。、！？]+$', ''),
        regexp_replace(s.text, '[。、！？「」]', '', 'g')
      ) || CASE WHEN k.kana IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(
        k.kana,
        regexp_replace(k.kana, '[。、！？]+$', ''),
        regexp_replace(k.kana, '[。、！？「」]', '', 'g')
      ) END
    ),
    updated_at = now()
FROM sentences s
LEFT JOIN LATERAL (
  SELECT string_agg(COALESCE(e.seg ->> 'r', e.seg ->> 't'), '' ORDER BY st.index, e.ord) AS kana
  FROM sentence_tokens st
  CROSS JOIN LATERAL jsonb_array_elements(st.furigana) WITH ORDINALITY e(seg, ord)
  WHERE st.sentence_id = s.id
) k ON true
WHERE p.id LIKE 'ep-dict-%' AND s.id = p.assets ->> 'sentenceId';
